const candidateBody = z.object({ tag: z.string() });
const displayBody = z.object({ showConsole: z.boolean() });
const exportBody = z.object({ includeSecrets: z.boolean().optional(), password: z.string().optional() });
const extractBody = z.object({ expectedRevision: z.number().int(), groups: z.array(z.object({ name: z.string(), encrypted: z.boolean(), uses: z.array(z.object({ service: z.string(), key: z.string() })) })), message: z.string().optional() });
const cleanBody = z.object({ compose: z.string() });
const analyzeBody = z.object({ compose: z.string(), variables: z.record(z.string(), z.string()).optional(), env: z.string().optional(), extract: z.array(z.object({ name: z.string(), encrypted: z.boolean(), uses: z.array(z.object({ service: z.string(), key: z.string() })) })).optional(), hostId: z.string().optional(), project: z.string().optional() });
const abandonBody = z.object({ reason: z.string().optional() });
const ignoreTagBody = z.object({ tag: z.string(), reason: z.string().optional() });
const imageTagBody = z.object({ expectedRevision: z.number().int(), tag: z.string(), message: z.string().optional() });
const customImageBody = z.object({ expectedRevision: z.number().int(), packageManager: z.string(), packages: z.array(z.string()), upgrade: z.boolean(), user: z.string(), dockerfile: z.string().optional(), message: z.string().optional() });
const acceptBody = z.object({ cve: z.string(), imageRef: z.string().optional(), justification: z.string(), days: z.number().int() });
const iconBody = z.object({ svg: z.string().nullable().optional(), color: z.string().nullable().optional() });

